const MAX_RENEWALS = 2;
const LOAN_DAYS = 14;

function renewLoan(loan, today) {
  if (loan.holds > 0) return { ok: false, reason: 'ON_HOLD' };
  if (loan.renewals >= MAX_RENEWALS) return { ok: false, reason: 'LIMIT' };
  const startDay = Math.max(loan.dueDay, today);
  return { ok: true, loan: { ...loan, renewals: loan.renewals + 1, dueDay: startDay + LOAN_DAYS } };
}

