const HOLD_MS = 10 * 60 * 1000;

function createHoldStore(clock) {
  const holds = new Map(); // seatId -> { userId, at }
  const active = seatId => {
    const h = holds.get(seatId);
    return h && clock.now() - h.at < HOLD_MS ? h : null;
  };
  return {
    hold(seatId, userId) {
      const h = active(seatId);
      if (h && h.userId !== userId) return false;          // someone else has it
      holds.set(seatId, { userId, at: clock.now() });      // new hold, or refresh own hold
      return true;
    },
    holderOf(seatId) {
      const h = active(seatId);
      return h ? h.userId : null;
    },
    release(seatId, userId) {
      const h = active(seatId);
      if (!h || h.userId !== userId) return false;
      holds.delete(seatId);
      return true;
    },
  };
}

// Reference learner suite. `createHoldStore` is in scope. No fake timers: the clock is injected.
function fakeClock(start = 0) {
  let t = start;
  return { now: () => t, advance: ms => { t += ms; } };
}
const MIN = 60 * 1000;

describe('seat holds', () => {
  let clock, store;
  beforeEach(() => { clock = fakeClock(); store = createHoldStore(clock); });

  it('lets the first buyer hold a free seat', () => {
    expect(store.hold('A1', 'ana')).toBe(true);
    expect(store.holderOf('A1')).toBe('ana');
  });
  it('blocks a second buyer while the hold is active', () => {
    store.hold('A1', 'ana');
    expect(store.hold('A1', 'ben')).toBe(false);
    expect(store.holderOf('A1')).toBe('ana');
  });
  it('keeps the hold until just before 10 minutes', () => {
    store.hold('A1', 'ana');
    clock.advance(10 * MIN - 1);
    expect(store.holderOf('A1')).toBe('ana');
  });
  it('expires the hold at exactly 10 minutes', () => {
    store.hold('A1', 'ana');
    clock.advance(10 * MIN);
    expect(store.holderOf('A1')).toBeNull();
    expect(store.hold('A1', 'ben')).toBe(true);
  });
  it('refreshes the timer when the same buyer holds again', () => {
    store.hold('A1', 'ana');
    clock.advance(8 * MIN);
    store.hold('A1', 'ana');
    clock.advance(8 * MIN);
    expect(store.holderOf('A1')).toBe('ana');
  });
  it('lets the holder release the seat for others', () => {
    store.hold('A1', 'ana');
    expect(store.release('A1', 'ana')).toBe(true);
    expect(store.hold('A1', 'ben')).toBe(true);
  });
  it('does not let someone else release the hold', () => {
    store.hold('A1', 'ana');
    expect(store.release('A1', 'ben')).toBe(false);
    expect(store.holderOf('A1')).toBe('ana');
  });
});

