function buildAuditReport(tests) {
  const totalMs = tests.reduce((sum, t) => sum + t.ms, 0);
  const slowest = tests.length
    ? tests.reduce((a, b) => (b.ms > a.ms ? b : a)).name
    : null;
  const flaky = tests.filter(t => t.flakyRuns > 0).map(t => t.name);
  // t is redundant if it catches no mutants at all, or if some other test u catches
  // every mutant t catches and u is faster, or equally fast and listed earlier
  // (so exact duplicates flag only one copy).
  const redundant = tests
    .filter((t, i) => t.kills.length === 0 || tests.some((u, j) =>
      j !== i &&
      t.kills.every(k => u.kills.includes(k)) &&
      (u.ms < t.ms || (u.ms === t.ms && j < i))))
    .map(t => t.name);
  return { totalMs, slowest, flaky, redundant };
}

