function mutationScore(mutants) {
  const counted = mutants.filter(m => m.status !== 'equivalent');
  if (counted.length === 0) return null;
  const detected = counted.filter(m => m.status === 'killed' || m.status === 'timeout').length;
  return {
    score: Math.round((100 * detected) / counted.length),
    survivors: counted.filter(m => m.status === 'survived' || m.status === 'noCoverage').map(m => m.id),
  };
}

